    // Each form checked, or its memo's change made again, as `check-tops`
    // (check-defs.kfx) does; `chain` the fingerprint of all before it. Modules
    // are checked always, and continue the chain by their text.

    // A module's order, kept by its text (C92): an unchanged module's is
    // not found again, every body of its walked.
    pub enum OrderMemo {
        OrderMemo(Sexps, Memos),
    }

    pub fn order_memo(f0: Sexps, f1: Memos) -> &'static OrderMemo {
        kayak_rt::heap_alloc(OrderMemo::OrderMemo(f0, f1))
    }

    #[inline]
    pub fn order_memo_forms(o: &'static OrderMemo) -> Sexps {
        let tagcase_ = o;
        match *tagcase_ {
            OrderMemo::OrderMemo(fs, ms) => {
                fs
            }
        }
    }

    #[inline]
    pub fn order_memo_made(o: &'static OrderMemo) -> Memos {
        let tagcase_ = o;
        match *tagcase_ {
            OrderMemo::OrderMemo(fs, ms) => {
                ms
            }
        }
    }

    pub fn module_order_memo(v: &'static Cv, forms: Sexps, text: Str, old: Memos, made: Memos) -> &'static OrderMemo {
        let key = fnv_string(text, fnv_string(str_lit("order"), fnv_offset()));
        let hit = memo_find(old, key);
        if null_p(hit) {
            let tagcase_ = module_order_coded(v, forms);
            match *tagcase_ {
                Ordered::Ordered(fs, code) => {
                    order_memo(fs, kayak_rt::heap_cons(memo(key, code), made))
                }
            }
        } else {
            let tagcase_ = car(hit);
            match *tagcase_ {
                Memo::Memo(h, code) => {
                    order_memo(order_from_code(forms, code), kayak_rt::heap_cons(car(hit), made))
                }
            }
        }
    }

    /// Positions, ascending (an insertion each: a module has tens of items).
    pub fn sorted_positions(mut ps: List<i64>, mut acc: List<i64>) -> List<i64> {
        loop {
            if null_p(ps) {
                return acc;
            } else {
                (ps, acc) = (cdr(ps), inserted(car(ps), acc));
                continue;
            }
        }
    }

    pub fn inserted(p: i64, ps: List<i64>) -> List<i64> {
        if null_p(ps) {
            kayak_rt::heap_cons(p, kayak_rt::nil())
        } else if i64_lt(p, car(ps)) {
            kayak_rt::heap_cons(p, ps)
        } else {
            kayak_rt::heap_cons(car(ps), inserted(p, cdr(ps)))
        }
    }

    pub fn position_after(mut p: i64, mut ps: List<i64>, mut end: i64) -> i64 {
        loop {
            if null_p(ps) {
                return end;
            } else if i64_gt(car(ps), p) {
                return car(ps);
            } else {
                ps = cdr(ps);
                continue;
            }
        }
    }

    /// The start of the item `p` is in: the last of `ps`, in order, not after it.
    pub fn item_start(mut p: i64, mut ps: List<i64>, mut last: i64) -> i64 {
        loop {
            if null_p(ps) {
                return last;
            } else if i64_gt(car(ps), p) {
                return last;
            } else {
                (ps, last) = (cdr(ps), car(ps));
                continue;
            }
        }
    }

    /// The items' starts a group checked at `start` has its members in (a
    /// `define-rec` the order made, `rec-of`, of items and their
    /// `define-rec`s), `start` first, each once.
    pub fn starts_of(start: i64, members: List<i64>, positions: List<i64>) -> List<i64> {
        if null_p(members) {
            kayak_rt::heap_cons(start, kayak_rt::nil())
        } else {
            let (rest, q) = (starts_of(start, cdr(members), positions), item_start(car(members), positions, -1i64));
            if (i64_lt(q, 0i64) || any_p(lambda1s(move |r: i64| {
                i64_eq(r, q)
            }), rest)) {
                rest
            } else {
                onto(rest, kayak_rt::heap_cons(q, kayak_rt::nil()))
            }
        }
    }

    /// A module's items, as `check-items` (check-defs.kfx), each its memo's
    /// change if it has one, keyed by its printed form and the chain.
    pub fn check_items_memo(v: &'static Cv, m: Str, its: Sexps, old: Memos, r: &'static Reads, found: Typeds, made: Memos, src: Str, from: i64, positions: List<i64>, end: i64) -> &'static CheckedMemo {
        if null_p(its) {
            checked_memo(v, found, made)
        } else {
            let it = car(its);
            let file = datum_file(it);
            let start = datum_pos(it);
            let slice = lambda1s(move |p: i64| {
                text_between(src, from, p, position_after(p, positions, end))
            });
            let placed = (i64_gt_eq(start, from) && i64_lt(start, end));
            let ss = if placed {
                starts_of(start, if head_is_p(it, str_lit("define-rec")) {
                    map(&datum_pos, cdr(items(it)))
                } else {
                    nil::<i64>()
                }, positions)
            } else {
                nil::<i64>()
            };
            let own = if placed {
                concat_strings(map(slice, ss))
            } else {
                show_sexp(it)
            };
            let es = map(lambda1s(move |q: i64| {
                position_after(q, positions, end)
            }), ss);
            let kd = reads_key(v, r, it, fnv_string(str_lit("item"), fnv_offset()));
            let key = fnv_string(own, keyed_key(kd));
            let r = keyed_reads(kd);
            let hit = memo_find(old, key);
            if not(null_p(hit)) {
                let tagcase_ = car(hit);
                match *tagcase_ {
                    Memo::Memo(h, text) => {
                        let tagcase_ = change_applied(v, text, if placed {
                            lambda1s(move |e: &'static FactRec| {
                                code_fact_at(file, ss, e)
                            })
                        } else {
                            lambda1s(move |e: &'static FactRec| {
                                code_fact(file, start, e)
                            })
                        });
                        match *tagcase_ {
                            Redone::Redone(v2, more, ambient) => {
                                check_items_memo(v2, m, cdr(its), old, reads_after(r, v2, ambient), onto(more, found), kayak_rt::heap_cons(car(hit), made), src, from, positions, end)
                            }
                        }
                    }
                }
            } else {
                let tagcase_ = check_item(v, m, it);
                match *tagcase_ {
                    Elab::Elab(v2, more) => {
                        let tagcase_ = change_of(v, v2, more, if placed {
                            lambda1s(move |x: &'static Fact| {
                                fact_code_at(file, ss, es, x)
                            })
                        } else {
                            lambda1s(move |x: &'static Fact| {
                                fact_code(file, start, x)
                            })
                        });
                        match *tagcase_ {
                            Change::Change(text2, ambient) => {
                                check_items_memo(v2, m, cdr(its), old, reads_after(r, v2, ambient), onto(more, found), kayak_rt::heap_cons(memo(key, text2), made), src, from, positions, end)
                            }
                        }
                    }
                }
            }
        }
    }

    pub fn check_tops_memo(mut v: &'static Cv, mut forms: Sexps, mut texts: Strings, mut old: Memos, mut r: &'static Reads, mut found: Typeds, mut made: Memos) -> &'static CheckedMemo {
        loop {
            if null_p(forms) {
                return checked_memo(v, found, made);
            } else {
                let form = car(forms);
                let file = datum_file(form);
                let start = datum_pos(form);
                let kd = reads_key(v, r, form, fnv_string(str_lit("check"), fnv_offset()));
                let key = fnv_string(car(texts), keyed_key(kd));
                let hit = memo_find(old, key);
                if module_def_p(form) {
                    // A module (C91): its items each with a memo, on a chain begun
                    // from the module's name and its items that are no values (its
                    // scope); the chain after it goes on with its change, as a
                    // form's does, so an edit inside an item's body leaves the
                    // forms after the module as they were.
                    let tagcase_ = form;
                    match *tagcase_ {
                        Sexp::Lst(xs, src_file, src_line, src_pos) => {
                            let p = module_prep(near(v, src_file, src_line, src_pos), form);
                            let inner = prep_inner(p);
                            let ordering = module_order_memo(inner, prep_forms(p), car(texts), old, made);
                            let scope = fnv_strings(kayak_rt::heap_cons(prep_name(p), concat(map(lambda1s(move |f: &'static Sexp| {
                                if null_p(item_value(f)) {
                                    the::<Strings>(kayak_rt::heap_cons(show_sexp(f), kayak_rt::nil()))
                                } else {
                                    nil::<Str>()
                                }
                            }), unhidden(module_written(form))))), fnv_string(str_lit("module"), reads_chain(r)));
                            let tagcase_ = check_items_memo(inner, prep_name(p), order_memo_forms(ordering), old, reads_anew(r, inner, i64_to_string(scope)), nil::<&'static Typed>(), order_memo_made(ordering), car(texts), start, sorted_positions(map(&datum_pos, unhidden(module_written(form))), nil::<i64>()), if null_p(cdr(texts)) {
                                end_of_file()
                            } else {
                                i64_plus(start, string_length_i64(car(texts)))
                            });
                            match *tagcase_ {
                                CheckedMemo::CheckedMemo(done, items_found, made2) => {
                                    let tagcase_ = module_finish(p, elab(done, items_found));
                                    match *tagcase_ {
                                        Elab::Elab(v2, more) => {
                                            (v, forms, texts, r, found, made) = (at(v2, str_lit(""), nil::<Str>()), cdr(forms), cdr(texts), reads_anew(r, v2, ambient_of(v, v2)), onto(more, found), made2);
                                            continue;
                                        }
                                    }
                                }
                            }
                        }
                        _ => {
                            let other = tagcase_;
                            (forms, texts) = (cdr(forms), cdr(texts));
                            continue;
                        }
                    }
                } else if not(null_p(hit)) {
                    let tagcase_ = car(hit);
                    match *tagcase_ {
                        Memo::Memo(h, text) => {
                            let tagcase_ = change_applied(v, text, lambda1s(move |e: &'static FactRec| {
                                code_fact(file, start, e)
                            }));
                            match *tagcase_ {
                                Redone::Redone(v2, more, ambient) => {
                                    (v, forms, texts, r, found, made) = (v2, cdr(forms), cdr(texts), reads_after(keyed_reads(kd), v2, ambient), onto(more, found), kayak_rt::heap_cons(car(hit), made));
                                    continue;
                                }
                            }
                        }
                    }
                } else {
                    let done = if untyped_p(form) {
                        let tagcase_ = form;
                        match *tagcase_ {
                            Sexp::Lst(xs, src_file, src_line, src_pos) => {
                                let tagcase_ = check_untyped(near(v, src_file, src_line, src_pos), form);
                                match *tagcase_ {
                                    Elab::Elab(v2, more) => {
                                        elab(at(v2, str_lit(""), nil::<Str>()), more)
                                    }
                                }
                            }
                            _ => {
                                let other = tagcase_;
                                elab(v, nil::<&'static Typed>())
                            }
                        }
                    } else {
                        elab(check_top(v, form), nil::<&'static Typed>())
                    };
                    let tagcase_ = done;
                    match *tagcase_ {
                        Elab::Elab(v2, more) => {
                            let tagcase_ = change_of(v, v2, more, lambda1s(move |x: &'static Fact| {
                                fact_code(file, start, x)
                            }));
                            match *tagcase_ {
                                Change::Change(text, ambient) => {
                                    (v, forms, texts, r, found, made) = (v2, cdr(forms), cdr(texts), reads_after(keyed_reads(kd), v2, ambient), onto(more, found), kayak_rt::heap_cons(memo(key, text), made));
                                    continue;
                                }
                            }
                        }
                    }
                }
            }
        }
    }

